using System.Windows;using System.Windows.Controls;using System.Windows.Data;using System.Windows.Media;using PhotoBooth.Color.D3D11;using PhotoBooth.Customer.UI.ViewModels;namespace PhotoBooth.Customer.UI.Views { public partial class CaptureView:UserControl { public CaptureView(){InitializeComponent();Loaded+=(s,e)=>{BindSize(this);ApplyOrientation();};SizeChanged+=(s,e)=>ApplyOrientation();}void ApplyOrientation(){var portrait=ActualHeight>ActualWidth*1.08;if(portrait){ReviewImageColumn.Width=new GridLength(1,GridUnitType.Star);ReviewListColumn.Width=new GridLength(0);ReviewImageRow.Height=new GridLength(1,GridUnitType.Star);ReviewListRow.Height=new GridLength(260);Grid.SetRow(ReviewImagePanel,0);Grid.SetColumn(ReviewImagePanel,0);Grid.SetColumnSpan(ReviewImagePanel,2);ReviewImagePanel.Margin=new Thickness(0,0,0,10);Grid.SetRow(ReviewListPanel,1);Grid.SetColumn(ReviewListPanel,0);Grid.SetColumnSpan(ReviewListPanel,2);}else{ReviewImageColumn.Width=new GridLength(1,GridUnitType.Star);ReviewListColumn.Width=new GridLength(230);ReviewImageRow.Height=new GridLength(1,GridUnitType.Star);ReviewListRow.Height=new GridLength(0);Grid.SetRow(ReviewImagePanel,0);Grid.SetColumn(ReviewImagePanel,0);Grid.SetColumnSpan(ReviewImagePanel,1);ReviewImagePanel.Margin=new Thickness(0,0,12,0);Grid.SetRow(ReviewListPanel,0);Grid.SetColumn(ReviewListPanel,1);Grid.SetColumnSpan(ReviewListPanel,1);}}void OnGpuLiveColorFailed(object sender,LiveColorFailedEventArgs e){(DataContext as CaptureViewModel)?.LiveColor.Disable(e.Error);}static void BindSize(DependencyObject root){for(var i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var child=VisualTreeHelper.GetChild(root,i);var surface=child as LiveColorSurface;if(surface!=null){BindingOperations.SetBinding(surface,LiveColorSurface.FrameWidthProperty,new Binding(nameof(CaptureViewModel.LiveFrameWidth)));BindingOperations.SetBinding(surface,LiveColorSurface.FrameHeightProperty,new Binding(nameof(CaptureViewModel.LiveFrameHeight)));}BindSize(child);}} } }
